def T(lam,p):
    mu=sum(a*b for a,b in zip(lam,p))
    var=sum(b*(a-mu)**2 for a,b in zip(lam,p))
    return [sp.cancel(b*(a-mu)**2/var) for a,b in zip(lam,p)]
def variance(lam,p):
    mu=sum(a*b for a,b in zip(lam,p))
    return sum(b*(a-mu)**2 for a,b in zip(lam,p))
